        var m=cnts[ri],step=(span-2*pad)/Math.max(1,m),off=(ri%2&&m>1)?step*.25:0;
        for(var q=0;q<m;q++){var s=items[ix++];var th=S.a0+pad+step*(q+.5)+off;POS[s.id]={th:th,r:r,x:r*Math.sin(th*Math.PI/180),y:-r*Math.cos(th*Math.PI/180)}}
