/* sweep + ping */
var PERIOD=7000,t0=performance.now(),prevA=0;
function frame(now){
  var a=((now-t0)/PERIOD*360)%360;
  $('sweep').style.transform='rotate('+a.toFixed(2)+'deg)';
  if(!document.hidden){
    SIG.forEach(function(s){
      var th=((POS[s.id].th%360)+360)%360;
      var hit=prevA<=a?(th>prevA&&th<=a):(th>prevA||th<=a);
      if(hit)ping(s);
    });
  }
  prevA=a;requestAnimationFrame(frame);
}
function ping(s){
  var d=$('d-'+s.id);if(!d||d.classList.contains('dim'))return;
  var p=POS[s.id],c=el('circle',{class:'ping',cx:p.x.toFixed(1),cy:p.y.toFixed(1),r:6,stroke:PRAC[s.p].cl});
  $('pings').appendChild(c);c.addEventListener('animationend',function(){c.remove()});
}

/* ---------- kijelölt jelzés ---------- */
