  Array.prototype.forEach.call(document.querySelectorAll('#rfg .dot'),function(d){d.classList.toggle('sel',d.getAttribute('data-id')===id)});
  var c=$('dcard');c.style.setProperty('--pc',P.c);c.style.setProperty('--pcl',P.cl);
