    var mixH=PORDER.map(function(p){return mix[p]?'<i style="flex-grow:'+mix[p]+';background:'+PRAC[p].c+'" title="'+PRAC[p].l+': '+mix[p]+'"></i>':''}).join('');
    var read=D.read.map(function(r){var s=SRC[r];return '<li><a href="'+esc(s.u)+'" target="_blank" rel="noopener noreferrer">'+esc(s.t)+'</a><time datetime="'+s.d+'">'+fmtD(s.d)+'</time></li>'}).join('');
    var tools=D.tools.map(function(t){var u=toolUrl(t[1]),ext=u.charAt(0)!=='#';return '<a class="tbtn" '+linkAttrs(u)+'>'+esc(t[0])+(ext?' ↗':'')+'</a>'}).join('');
